 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { mergeV3Tags } from "../../lib/operations";
import { ZV3MergeTagBody, ZV3TagIdParams } from "../../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
